  [[nodiscard]] std::uint64_t set_today_async(DayStats value, std::function<void(Result<DayStats>)> completion) { if (!completion) throw std::invalid_argument("Rivet async completion handler is empty"); return backend_.set_state_async("today", detail::encode_DayStats(value), [completion = std::move(completion)](rivet::windows::CallResult rivet_result) mutable { Result<DayStats> result; if (rivet_result.error) { result.error = rivet_result.error; } else { try { if (!rivet_result.value) throw std::runtime_error("Rivet async call completed without a value"); result.value = detail::decode_DayStats(*rivet_result.value); } catch (...) { result.error = std::current_exception(); } } completion(std::move(result)); }); }

